/// Helper: create a fresh FS image and return path.
fn fresh_image(tag: &str) -> String {
    let path = format!("/tmp/jfs_demo_{}.img", tag);
    FileSystem::format(Path::new(&path), 1024).expect("format");
    path
}

/// Helper: print a separator.
fn header(title: &str) {
    println!();
    println!("================================================================");
    println!("  {}", title);
    println!("================================================================");
}

fn pass(name: &str) {
