        FileOps::create(&mut *journal, &mut fs.cache, &mut fs.disk, &fs.sb, &name).unwrap();
        FileOps::write(&mut *journal, &mut fs.cache, &mut fs.disk, &fs.sb, &name, data.as_bytes()).unwrap();
    }
