use crate::block_cache::BlockCache;
use crate::bitmap::Bitmap;
use crate::disk::{Block, FileDisk, BLOCK_SIZE};
use crate::superblock::Superblock;

/// Inode types.
pub const INODE_NONE: u16 = 0;
pub const INODE_FILE: u16 = 1;
pub const INODE_DIR: u16 = 2;

/// Number of direct block pointers per inode.
pub const NDIRECT: usize = 12;
/// One indirect block pointer.
/// Total max file size = (NDIRECT + BLOCK_SIZE/4) * BLOCK_SIZE
pub const MAX_FILE_SIZE: usize = NDIRECT * BLOCK_SIZE;

/// On-disk inode (32 bytes).
#[derive(Debug, Clone, Copy)]
#[repr(C)]
pub struct DiskInode {
    pub itype: u16,          // 0=none, 1=file, 2=dir
    pub nlink: u16,          // number of hard links
    pub size: u32,           // file size in bytes
    pub direct: [u32; NDIRECT], // direct block pointers
}

impl DiskInode {
    pub fn zeroed() -> Self {
        Self {
            itype: INODE_NONE,
            nlink: 0,
            size: 0,
            direct: [0u32; NDIRECT],
        }
    }

    pub fn to_bytes(&self) -> [u8; 32] {
        let mut buf = [0u8; 32];
        buf[0..2].copy_from_slice(&self.itype.to_le_bytes());
        buf[2..4].copy_from_slice(&self.nlink.to_le_bytes());
        buf[4..8].copy_from_slice(&self.size.to_le_bytes());
        for i in 0..NDIRECT {
            let off = 8 + i * 4;
            buf[off..off + 4].copy_from_slice(&self.direct[i].to_le_bytes());
        }
        buf
    }

    pub fn from_bytes(buf: &[u8; 32]) -> Self {
        Self {
            itype: u16::from_le_bytes(buf[0..2].try_into().unwrap()),
            nlink: u16::from_le_bytes(buf[2..4].try_into().unwrap()),
            size: u32::from_le_bytes(buf[4..8].try_into().unwrap()),
            direct: {
                let mut d = [0u32; NDIRECT];
                for i in 0..NDIRECT {
                    let off = 8 + i * 4;
                    d[i] = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap());
                }
                d
            },
        }
    }
}

/// Number of inodes per block (512 / 32 = 16).
pub const INODES_PER_BLOCK: u32 = (BLOCK_SIZE / 32) as u32;

/// In-memory inode wrapper.
pub struct Inode {
    pub inum: u32,          // inode number
    pub disk: DiskInode,    // on-disk copy
    pub valid: bool,        // has been read from disk
    pub ref_count: u32,     // reference count
}

impl Inode {
    pub fn new(inum: u32) -> Self {
        Self {
            inum,
            disk: DiskInode::zeroed(),
            valid: false,
            ref_count: 0,
        }
    }
}

/// Inode operations.
pub struct InodeOps;

impl InodeOps {
    /// Allocate a new inode of the given type.
    /// Returns the inode number.
    pub fn ialloc(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        itype: u16,
    ) -> Option<u32> {
        for inum in 1..sb.ninodes {
            let block_no = sb.inode_start + inum / INODES_PER_BLOCK;
            let offset = ((inum % INODES_PER_BLOCK) * 32) as usize;

            let data = cache.read_mut(disk, block_no);
            let mut dinode = DiskInode::from_bytes((&data[offset..offset + 32]).try_into().unwrap());

            if dinode.itype == INODE_NONE {
                dinode = DiskInode::zeroed();
                dinode.itype = itype;
                dinode.nlink = 1;
                dinode.size = 0;
                data[offset..offset + 32].copy_from_slice(&dinode.to_bytes());
                return Some(inum);
            }
        }
        None
    }

    /// Read an inode from disk into the Inode struct.
    pub fn iget(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        inum: u32,
    ) -> DiskInode {
        assert!(inum > 0 && inum < sb.ninodes, "iget: invalid inode {}", inum);

        let block_no = sb.inode_start + inum / INODES_PER_BLOCK;
        let offset = ((inum % INODES_PER_BLOCK) * 32) as usize;

        let data = cache.read(disk, block_no);
        DiskInode::from_bytes((&data[offset..offset + 32]).try_into().unwrap())
    }

    /// Write an inode back to disk (through cache).
    pub fn iupdate(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        inum: u32,
        dinode: &DiskInode,
    ) {
        let block_no = sb.inode_start + inum / INODES_PER_BLOCK;
        let offset = ((inum % INODES_PER_BLOCK) * 32) as usize;

        let data = cache.read_mut(disk, block_no);
        data[offset..offset + 32].copy_from_slice(&dinode.to_bytes());
    }

    /// Allocate a data block for an inode.
    /// Returns the block number of the newly allocated block.
    pub fn balloc(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
    ) -> Option<u32> {
        let ndata = sb.ndata_blocks();
        let bnum = Bitmap::alloc(cache, disk, sb.data_bitmap, ndata)?;
        // The actual disk block number
        let block_no = sb.data_start + bnum;
        // Zero the new block
        let data = cache.read_mut(disk, block_no);
        *data = [0u8; BLOCK_SIZE];
        Some(block_no)
    }

    /// Free a data block.
    pub fn bfree(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        block_no: u32,
    ) {
        assert!(block_no >= sb.data_start, "bfree: not a data block");
        let bnum = block_no - sb.data_start;
        Bitmap::free(cache, disk, sb.data_bitmap, bnum);
    }

    /// Read data from an inode. Returns the number of bytes read.
    pub fn readi(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        dinode: &DiskInode,
        buf: &mut [u8],
        offset: u32,
    ) -> usize {
        let size = dinode.size;
        if offset >= size {
            return 0;
        }
        let end = std::cmp::min(offset + buf.len() as u32, size);
        let mut bytes_read = 0usize;
        let mut off = offset;

        while off < end {
            let block_idx = (off / BLOCK_SIZE as u32) as usize;
            let block_off = (off % BLOCK_SIZE as u32) as usize;
            let bytes_left = (end - off) as usize;
            let chunk = std::cmp::min(bytes_left, BLOCK_SIZE - block_off);

            if block_idx >= NDIRECT {
                break;
            }

            let data_block = dinode.direct[block_idx];
            if data_block == 0 {
                // Hole — fill with zeros
                buf[bytes_read..bytes_read + chunk].fill(0);
            } else {
                let data = cache.read(disk, data_block);
                buf[bytes_read..bytes_read + chunk]
                    .copy_from_slice(&data[block_off..block_off + chunk]);
            }

            bytes_read += chunk;
            off += chunk as u32;
        }

        bytes_read
    }

    /// Write data to an inode. Returns the number of bytes written.
    pub fn writei(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        dinode: &mut DiskInode,
        inum: u32,
        buf: &[u8],
        offset: u32,
    ) -> usize {
        let mut bytes_written = 0usize;
        let mut off = offset;

        while bytes_written < buf.len() {
            let block_idx = (off / BLOCK_SIZE as u32) as usize;
            let block_off = (off % BLOCK_SIZE as u32) as usize;
            let bytes_left = buf.len() - bytes_written;
            let chunk = std::cmp::min(bytes_left, BLOCK_SIZE - block_off);

            if block_idx >= NDIRECT {
                break;
            }

            // Allocate block if needed
            if dinode.direct[block_idx] == 0 {
                match Self::balloc(cache, disk, sb) {
                    Some(b) => dinode.direct[block_idx] = b,
                    None => break,
                }
            }

            let data_block = dinode.direct[block_idx];
            let data = cache.read_mut(disk, data_block);
            let src_start = bytes_written;
            data[block_off..block_off + chunk]
                .copy_from_slice(&buf[src_start..src_start + chunk]);

            bytes_written += chunk;
            off += chunk as u32;
        }

        // Update inode size
        let new_size = std::cmp::max(dinode.size, offset + bytes_written as u32);
        dinode.size = new_size;

        Self::iupdate(cache, disk, sb, inum, dinode);
        bytes_written
    }
}

use crate::block_cache::BlockCache;
use crate::disk::{Block, FileDisk, BLOCK_SIZE};
use crate::inode::{DiskInode, InodeOps, INODE_DIR, INODE_NONE, INODES_PER_BLOCK};
use crate::superblock::Superblock;

/// Directory entry: 32 bytes each, 16 entries per block.
/// [0..4]   inode number (u32)
/// [4..32]  name ([u8; 28])
pub const DIRSIZ: usize = 28;
pub const DIRENT_SIZE: usize = 32;
pub const DIRENTS_PER_BLOCK: usize = BLOCK_SIZE / DIRENT_SIZE; // 16

#[derive(Debug, Clone, Copy)]
pub struct DirEntry {
    pub inum: u32,
    pub name: [u8; DIRSIZ],
}

impl DirEntry {
    pub fn empty() -> Self {
        Self {
            inum: 0,
            name: [0u8; DIRSIZ],
        }
    }

    pub fn new(inum: u32, name: &str) -> Self {
        let mut entry = Self::empty();
        entry.inum = inum;
        let bytes = name.as_bytes();
        let len = std::cmp::min(bytes.len(), DIRSIZ);
        entry.name[..len].copy_from_slice(&bytes[..len]);
        entry
    }

    pub fn name_str(&self) -> &str {
        let end = self.name.iter().position(|&b| b == 0).unwrap_or(DIRSIZ);
        std::str::from_utf8(&self.name[..end]).unwrap_or("")
    }

    pub fn to_bytes(&self) -> [u8; DIRENT_SIZE] {
        let mut buf = [0u8; DIRENT_SIZE];
        buf[0..4].copy_from_slice(&self.inum.to_le_bytes());
        buf[4..4 + DIRSIZ].copy_from_slice(&self.name);
        buf
    }

    pub fn from_bytes(buf: &[u8; DIRENT_SIZE]) -> Self {
        Self {
            inum: u32::from_le_bytes(buf[0..4].try_into().unwrap()),
            name: {
                let mut name = [0u8; DIRSIZ];
                name.copy_from_slice(&buf[4..4 + DIRSIZ]);
                name
            },
        }
    }
}

/// Root inode number.
pub const ROOT_INUM: u32 = 1;

/// Directory operations.
pub struct DirOps;

impl DirOps {
    /// Look up a directory entry by name. Returns the inode number.
    pub fn lookup(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        dir_inum: u32,
        name: &str,
    ) -> Option<u32> {
        let dinode = InodeOps::iget(cache, disk, sb, dir_inum);
        if dinode.itype != INODE_DIR {
            return None;
        }

        let name_bytes = name.as_bytes();
        let len = std::cmp::min(name_bytes.len(), DIRSIZ);

        for block_idx in 0..dinode.size as usize / BLOCK_SIZE {
            let data_block = dinode.direct[block_idx];
            if data_block == 0 {
                continue;
            }
            let data = cache.read(disk, data_block);
            for i in 0..DIRENTS_PER_BLOCK {
                let off = i * DIRENT_SIZE;
                let entry = DirEntry::from_bytes((&data[off..off + DIRENT_SIZE]).try_into().unwrap());
                if entry.inum == 0 {
                    continue;
                }
                if entry.name[..len] == name_bytes[..len]
                    && (len == DIRSIZ || entry.name[len] == 0)
                {
                    return Some(entry.inum);
                }
            }
        }
        None
    }

    /// Link a new entry into a directory.
    pub fn link(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        dir_inum: u32,
        name: &str,
        child_inum: u32,
    ) -> Result<(), String> {
        // Check if name already exists
        if Self::lookup(cache, disk, sb, dir_inum, name).is_some() {
            return Err(format!("link: {} already exists", name));
        }

        let mut dinode = InodeOps::iget(cache, disk, sb, dir_inum);
        if dinode.itype != INODE_DIR {
            return Err("link: not a directory".to_string());
        }

        let new_entry = DirEntry::new(child_inum, name);

        // Find a free slot or append
        for block_idx in 0..crate::inode::NDIRECT {
            if dinode.direct[block_idx] == 0 {
                // Allocate a new block for directory
                let new_block = InodeOps::balloc(cache, disk, sb)
                    .ok_or("link: no free blocks")?;
                dinode.direct[block_idx] = new_block;

                // Update dir size
                dinode.size = ((block_idx + 1) * BLOCK_SIZE) as u32;
                InodeOps::iupdate(cache, disk, sb, dir_inum, &dinode);

                // Write the new entry at the beginning of the new block
                let data = cache.read_mut(disk, new_block);
                data[0..DIRENT_SIZE].copy_from_slice(&new_entry.to_bytes());
                return Ok(());
            }

            let data = cache.read(disk, dinode.direct[block_idx]);
            for i in 0..DIRENTS_PER_BLOCK {
                let off = i * DIRENT_SIZE;
                let entry = DirEntry::from_bytes((&data[off..off + DIRENT_SIZE]).try_into().unwrap());
                if entry.inum == 0 {
                    // Found a free slot
                    let data = cache.read_mut(disk, dinode.direct[block_idx]);
                    data[off..off + DIRENT_SIZE].copy_from_slice(&new_entry.to_bytes());
                    return Ok(());
                }
            }
        }

        Err("link: directory full".to_string())
    }

    /// Unlink an entry from a directory.
    pub fn unlink(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        dir_inum: u32,
        name: &str,
    ) -> Result<u32, String> {
        let mut dinode = InodeOps::iget(cache, disk, sb, dir_inum);
        if dinode.itype != INODE_DIR {
            return Err("unlink: not a directory".to_string());
        }

        let name_bytes = name.as_bytes();
        let len = std::cmp::min(name_bytes.len(), DIRSIZ);

        for block_idx in 0..crate::inode::NDIRECT {
            let data_block = dinode.direct[block_idx];
            if data_block == 0 {
                continue;
            }
            let data = cache.read(disk, data_block);
            for i in 0..DIRENTS_PER_BLOCK {
                let off = i * DIRENT_SIZE;
                let entry = DirEntry::from_bytes((&data[off..off + DIRENT_SIZE]).try_into().unwrap());
                if entry.inum == 0 {
                    continue;
                }
                if entry.name[..len] == name_bytes[..len]
                    && (len == DIRSIZ || entry.name[len] == 0)
                {
                    let freed_inum = entry.inum;
                    // Clear the entry
                    let data = cache.read_mut(disk, data_block);
                    data[off..off + DIRENT_SIZE].copy_from_slice(&DirEntry::empty().to_bytes());

                    // Decrement nlink
                    let mut child = InodeOps::iget(cache, disk, sb, freed_inum);
                    child.nlink = child.nlink.saturating_sub(1);
                    if child.nlink == 0 {
                        // Free data blocks
                        for &b in &child.direct {
                            if b != 0 {
                                InodeOps::bfree(cache, disk, sb, b);
                            }
                        }
                        child = DiskInode::zeroed();
                    }
                    InodeOps::iupdate(cache, disk, sb, freed_inum, &child);

                    return Ok(freed_inum);
                }
            }
        }

        Err(format!("unlink: {} not found", name))
    }

    /// List directory entries.
    pub fn list(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        dir_inum: u32,
    ) -> Vec<(String, u32, u16)> {
        let mut entries = Vec::new();
        let dinode = InodeOps::iget(cache, disk, sb, dir_inum);
        if dinode.itype != INODE_DIR {
            return entries;
        }

        // First pass: collect (name, inum) pairs
        let mut raw: Vec<(String, u32)> = Vec::new();
        for block_idx in 0..crate::inode::NDIRECT {
            let data_block = dinode.direct[block_idx];
            if data_block == 0 {
                continue;
            }
            let data = cache.read(disk, data_block);
            for i in 0..DIRENTS_PER_BLOCK {
                let off = i * DIRENT_SIZE;
                let entry = DirEntry::from_bytes((&data[off..off + DIRENT_SIZE]).try_into().unwrap());
                if entry.inum != 0 {
                    raw.push((entry.name_str().to_string(), entry.inum));
                }
            }
        }
        // Second pass: look up inode types
        for (name, inum) in raw {
            let child = InodeOps::iget(cache, disk, sb, inum);
            entries.push((name, inum, child.itype));
        }
        entries
    }

    /// Initialize the root directory.
    pub fn init_root(cache: &mut BlockCache, disk: &mut FileDisk, sb: &Superblock) {
        // Root inode should already be allocated as INODE_DIR
        let mut dinode = InodeOps::iget(cache, disk, sb, ROOT_INUM);
        dinode.itype = INODE_DIR;
        dinode.nlink = 1;
        dinode.size = 0;

        // Allocate a data block for root dir
        let block = InodeOps::balloc(cache, disk, sb).expect("init_root: no free blocks");
        dinode.direct[0] = block;
        dinode.size = BLOCK_SIZE as u32;

        // Add "." and ".." entries
        let data = cache.read_mut(disk, block);
        let dot = DirEntry::new(ROOT_INUM, ".");
        let dotdot = DirEntry::new(ROOT_INUM, "..");
        data[0..DIRENT_SIZE].copy_from_slice(&dot.to_bytes());
        data[DIRENT_SIZE..2 * DIRENT_SIZE].copy_from_slice(&dotdot.to_bytes());

        InodeOps::iupdate(cache, disk, sb, ROOT_INUM, &dinode);
    }
}

use crate::block_cache::BlockCache;
use crate::disk::FileDisk;
use crate::dir::DirOps;
use crate::inode::{InodeOps, INODE_FILE, INODE_NONE};
use crate::log::Journal;
use crate::superblock::Superblock;

/// High-level file operations that wrap journaling.
pub struct FileOps;

impl FileOps {
    /// Create a new file in the root directory.
    /// Returns the new inode number.
    pub fn create(
        journal: &mut dyn Journal,
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        name: &str,
    ) -> Result<u32, String> {
        journal.begin_tx();

        // Allocate inode
        let inum = InodeOps::ialloc(cache, disk, sb, INODE_FILE)
            .ok_or("create: no free inodes")?;

        // Initialize inode data
        let mut dinode = crate::inode::DiskInode::zeroed();
        dinode.itype = INODE_FILE;
        dinode.nlink = 1;
        dinode.size = 0;
        InodeOps::iupdate(cache, disk, sb, inum, &dinode);

        // Link into root directory
        DirOps::link(cache, disk, sb, crate::dir::ROOT_INUM, name, inum)?;

        journal.commit(disk, cache)?;

        Ok(inum)
    }

    /// Write data to a file.
    pub fn write(
        journal: &mut dyn Journal,
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        name: &str,
        data: &[u8],
    ) -> Result<usize, String> {
        let inum = DirOps::lookup(cache, disk, sb, crate::dir::ROOT_INUM, name)
            .ok_or_else(|| format!("write: {} not found", name))?;

        journal.begin_tx();

        let mut dinode = InodeOps::iget(cache, disk, sb, inum);
        let n = InodeOps::writei(cache, disk, sb, &mut dinode, inum, data, 0);

        journal.commit(disk, cache)?;

        Ok(n)
    }

    /// Append data to a file.
    pub fn append(
        journal: &mut dyn Journal,
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        name: &str,
        data: &[u8],
    ) -> Result<usize, String> {
        let inum = DirOps::lookup(cache, disk, sb, crate::dir::ROOT_INUM, name)
            .ok_or_else(|| format!("append: {} not found", name))?;

        journal.begin_tx();

        let mut dinode = InodeOps::iget(cache, disk, sb, inum);
        let offset = dinode.size;
        let n = InodeOps::writei(cache, disk, sb, &mut dinode, inum, data, offset);

        journal.commit(disk, cache)?;

        Ok(n)
    }

    /// Read data from a file.
    pub fn read(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        name: &str,
        buf: &mut [u8],
    ) -> Result<usize, String> {
        let inum = DirOps::lookup(cache, disk, sb, crate::dir::ROOT_INUM, name)
            .ok_or_else(|| format!("read: {} not found", name))?;

        let dinode = InodeOps::iget(cache, disk, sb, inum);
        Ok(InodeOps::readi(cache, disk, &dinode, buf, 0))
    }

    /// Read entire file as a String.
    pub fn read_string(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        name: &str,
    ) -> Result<String, String> {
        let inum = DirOps::lookup(cache, disk, sb, crate::dir::ROOT_INUM, name)
            .ok_or_else(|| format!("read: {} not found", name))?;

        let dinode = InodeOps::iget(cache, disk, sb, inum);
        let mut buf = vec![0u8; dinode.size as usize];
        let n = InodeOps::readi(cache, disk, &dinode, &mut buf, 0);
        buf.truncate(n);
        String::from_utf8(buf).map_err(|e| format!("utf8 error: {}", e))
    }

    /// Get file size.
    pub fn size(
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        name: &str,
    ) -> Result<u32, String> {
        let inum = DirOps::lookup(cache, disk, sb, crate::dir::ROOT_INUM, name)
            .ok_or_else(|| format!("size: {} not found", name))?;
        let dinode = InodeOps::iget(cache, disk, sb, inum);
        Ok(dinode.size)
    }

    /// Delete a file.
    pub fn unlink(
        journal: &mut dyn Journal,
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        name: &str,
    ) -> Result<(), String> {
        journal.begin_tx();
        DirOps::unlink(cache, disk, sb, crate::dir::ROOT_INUM, name)?;
        journal.commit(disk, cache)?;
        Ok(())
    }

    /// Rename a file.
    pub fn rename(
        journal: &mut dyn Journal,
        cache: &mut BlockCache,
        disk: &mut FileDisk,
        sb: &Superblock,
        old_name: &str,
        new_name: &str,
    ) -> Result<(), String> {
        let inum = DirOps::lookup(cache, disk, sb, crate::dir::ROOT_INUM, old_name)
            .ok_or_else(|| format!("rename: {} not found", old_name))?;

        journal.begin_tx();

        // Remove old name
        DirOps::unlink(cache, disk, sb, crate::dir::ROOT_INUM, old_name)?;

        // Add new name (increment nlink since unlink decremented it)
        let mut dinode = InodeOps::iget(cache, disk, sb, inum);
        dinode.nlink += 1;
        InodeOps::iupdate(cache, disk, sb, inum, &dinode);

        DirOps::link(cache, disk, sb, crate::dir::ROOT_INUM, new_name, inum)?;

        journal.commit(disk, cache)?;
        Ok(())
    }
}

