            let inode_block = sb.inode_start + 2 / crate::inode::INODES_PER_BLOCK;
            let offset = ((2 % crate::inode::INODES_PER_BLOCK) * crate::inode::INODE_SIZE as u32) as usize;
            let mut ibuf = [0u8; 512];
