            disk.write_block(sb.log_start + 1, &orig_data).unwrap();

            // Write committed header
            let mut hdr = [0u8; 512];
            hdr[0..4].copy_from_slice(&1u32.to_le_bytes());
            hdr[4..8].copy_from_slice(&1u32.to_le_bytes());
