            partial[0..9].copy_from_slice(b"CORRUPTED");
            disk.write_block(data_block, &partial).unwrap();

            drop(disk); // crash
        }

        // Recover with undo log
        {
            let mut fs = fs::FileSystem::mount(Path::new(path), fs::JournalType::Undo).unwrap();
