            hdr[0..4].copy_from_slice(&1u32.to_le_bytes());
            hdr[4..8].copy_from_slice(&1u32.to_le_bytes());
            hdr[8..12].copy_from_slice(&data_block.to_le_bytes());
            disk.write_block(sb.log_start, &hdr).unwrap();

