                    Ok(n) => println!("Appended {} bytes to '{}'", n, name),
                    Err(e) => println!("Error: {}", e),
                }
            }

            "read" => {
                let name = parts.get(1).unwrap_or(&"");
                if name.is_empty() {
                    println!("Usage: read <name>");
                    continue;
                }
                match file::FileOps::read_string(&mut fs.cache, &mut fs.disk, &fs.sb, name) {
                    Ok(content) => println!("{}", content),
                    Err(e) => println!("Error: {}", e),
                }
            }

            "rm" | "del" | "delete" | "unlink" => {
                let name = parts.get(1).unwrap_or(&"");
                if name.is_empty() {
                    println!("Usage: rm <name>");
                    continue;
                }
                let mut journal = fs.make_journal();
                match file::FileOps::unlink(&mut *journal, &mut fs.cache, &mut fs.disk, &fs.sb, name) {
                    Ok(()) => println!("Deleted '{}'", name),
                    Err(e) => println!("Error: {}", e),
                }
            }

            "mv" | "rename" => {
                let old = parts.get(1).unwrap_or(&"");
                let new = parts.get(2).unwrap_or(&"");
                if old.is_empty() || new.is_empty() {
                    println!("Usage: mv <old_name> <new_name>");
                    continue;
                }
                let mut journal = fs.make_journal();
                match file::FileOps::rename(&mut *journal, &mut fs.cache, &mut fs.disk, &fs.sb, old, new) {
                    Ok(()) => println!("Renamed '{}' -> '{}'", old, new),
                    Err(e) => println!("Error: {}", e),
                }
            }

            "stat" => {
                let name = parts.get(1).unwrap_or(&"");
                if name.is_empty() {
                    println!("Usage: stat <name>");
                    continue;
                }
                match dir::DirOps::lookup(&mut fs.cache, &mut fs.disk, &fs.sb, dir::ROOT_INUM, name) {
                    Some(inum) => {
                        let dinode = inode::InodeOps::iget(&mut fs.cache, &mut fs.disk, &fs.sb, inum);
                        let type_str = match dinode.itype {
                            0 => "NONE",
                            1 => "FILE",
                            2 => "DIR",
                            _ => "UNKNOWN",
                        };
                        println!("  File:     {}", name);
                        println!("  Inode:    {}", inum);
                        println!("  Type:     {}", type_str);
                        println!("  Size:     {} bytes", dinode.size);
                        println!("  Links:    {}", dinode.nlink);
                        println!("  Blocks:   {:?}", dinode.direct.iter().filter(|&&b| b != 0).collect::<Vec<_>>());
                    }
                    None => println!("'{}' not found", name),
                }
            }

            "touch" => {
                let name = parts.get(1).unwrap_or(&"");
                if name.is_empty() {
                    println!("Usage: touch <name>");
                    continue;
                }
                if dir::DirOps::lookup(&mut fs.cache, &mut fs.disk, &fs.sb, dir::ROOT_INUM, name).is_some() {
                    println!("'{}' already exists", name);
                } else {
                    let mut journal = fs.make_journal();
                    match file::FileOps::create(&mut *journal, &mut fs.cache, &mut fs.disk, &fs.sb, name) {
                        Ok(inum) => println!("Created '{}' (inode {})", name, inum),
                        Err(e) => println!("Error: {}", e),
                    }
                }
            }

            "stats" => {
                fs.stats();
            }

            "crash" => {
                println!("*** SIMULATING CRASH ***");
                println!("Dropping disk without sync or log cleanup...");
                // Take ownership of the disk and crash it
                // We need to destructure fs
                let disk = fs.disk; // move out
                disk.crash();
                println!("Crash complete. Image may be in inconsistent state.");
                println!("Re-mount with 'jfs shell' to see recovery in action.");
                return; // exit — fs is partially moved out
            }

            "journal" => {
                println!("Current journal type: {}", jtype);
            }

            "exit" | "quit" | "q" => {
                fs.umount();
                println!("Goodbye.");
                return;
            }

            "" => {}

            _ => {
                println!("Unknown command: '{}'. Type 'help' for available commands.", cmd);
            }
        }
    }

    // Clean exit on EOF
    fs.umount();
    println!("Goodbye.");
}

